import numpy as np
try:
    from scipy.optimize import least_squares
except Exception as e:
    print("noscipy",e)
y=dv_dt
def model(p):
    a,b,c,d,pw1,pw2,pw3,pw4,k,m=p
    f1=a*t**pw1*v
    f2=b*x**pw2*v
    f3=c*np.exp(-k*x)/v**m
    f4=d*t**pw3*np.exp(-x)*v**0
    return f1+f2+f3+f4
def resid(p):
    return (model(p)-y)/np.std(y)
